import {useCallback, useEffect, useState} from 'react';

import {Box, Button, Card, Flex, Text, TextInput, configure as configureUikit} from '@gravity-ui/uikit';
import {
    MarkdownEditorView,
    configure as configureMarkdownEditor,
    useMarkdownEditor,
    type MarkupString,
    type RenderPreview,
} from '@gravity-ui/markdown-editor';

import {SplitModePreview} from './SplitModePreview';

configureUikit({lang: 'ru'});
configureMarkdownEditor({lang: 'ru'});

const INITIAL_MARKUP = [
    '# Черновик статьи',
    '',
    'Напишите текст с **markdown**-разметкой — форматирование применится сразу.',
    '',
    '- списки,',
    '- `код`,',
    '- [ссылки](https://gravity-ui.com) и многое другое.',
    '',
].join('\n');

export function App() {
    const [title, setTitle] = useState('');
    const [submitted, setSubmitted] = useState<{title: string; body: MarkupString} | null>(null);

