                        <Flex direction="column" gap={1}>
                            <Text variant="subheader-2">Текст статьи</Text>
                            <Text variant="body-2" color="secondary">
                                Пишите с markdown-разметкой — форматирование отображается сразу. В режиме разметки можно включить предпросмотр рядом с текстом.
                            </Text>
                            <MarkdownEditorView stickyToolbar autofocus editor={editor} />
                        </Flex>
                        <Flex>
                            <Button view="action" size="l" type="submit">
                                Опубликовать
                            </Button>
                        </Flex>
                    </Flex>
                </form>
                {submitted && (
                    <Card view="filled" ...>
                        ...
                    </Card>
                )}
            </Flex>
        </Box>
    );
}
